// ─────────────────────────────────────────────────────────────────────────────
// Mock Target Account Scope (SANDBOX_MODE=true)
// Fictitious target accounts in the same raw shape the HubSpot and Google
// Sheets adapters emit. Includes one duplicate and one invalid domain so the
// normalisation stage can be verified.
// ─────────────────────────────────────────────────────────────────────────────
const DAY_MS = 24 * 60 * 60 * 1000;
const ago = (days) => new Date(Date.now() - days * DAY_MS).toISOString();
const baseline = (days, employees, departments, openRolesTarget) =>
  JSON.stringify({ capturedAt: ago(days), employees, departments, openRolesTarget });

const accounts = [
  { companyId: '600000001', name: 'Apex Dynamics Inc', domain: 'https://www.apex-dynamics.example', employees: 850, ownerId: '71000001',
    baselineJson: baseline(34, 790, { Engineering: 120, Sales: 60, Marketing: 25, 'Customer Success': 30 }, 3), lastScannedAt: ago(1), lastAlertedAt: null, tier: 'cool' },
  { companyId: '600000002', name: 'Brightline Robotics Ltd', domain: 'brightline-robotics.example', employees: 320, ownerId: '71000002',
    baselineJson: baseline(31, 305, { Engineering: 70, Sales: 30, Marketing: 12 }, 2), lastScannedAt: ago(1), lastAlertedAt: null, tier: 'cool' },
  { companyId: '600000003', name: 'Cobalt Ridge Analytics', domain: 'cobalt-ridge-analytics.example', employees: 140, ownerId: null,
    baselineJson: baseline(12, 138, { Engineering: 40, Sales: 15 }, 1), lastScannedAt: ago(1), lastAlertedAt: null, tier: 'cool' },
  { companyId: '600000004', name: 'Driftwood Health Systems', domain: 'driftwood-health.example', employees: 2100, ownerId: '71000001',
    baselineJson: '', lastScannedAt: null, lastAlertedAt: null, tier: '' },
  { companyId: '600000005', name: 'Apex Dynamics Inc (duplicate record)', domain: 'apex-dynamics.example', employees: 850, ownerId: null,
    baselineJson: '', lastScannedAt: null, lastAlertedAt: null, tier: '' },
  { companyId: '600000006', name: 'Placeholder Import Row', domain: 'not a domain', employees: null, ownerId: null,
    baselineJson: '', lastScannedAt: null, lastAlertedAt: null, tier: '' },
];

return [{ json: { source: 'synthetic-fixtures', pagesFetched: 0, accounts } }];

// ─────────────────────────────────────────────────────────────────────────────
// Flatten HubSpot Scope
// Collapses paginated CRM Search responses into one item with a raw
// `accounts` array, so downstream nodes always receive exactly one item.
// ─────────────────────────────────────────────────────────────────────────────
const accounts = [];
let pagesFetched = 0;

for (const item of $input.all()) {
  pagesFetched += 1;
  for (const r of Array.isArray(item.json.results) ? item.json.results : []) {
    const p = r.properties || {};
    accounts.push({
      companyId: String(r.id ?? p.hs_object_id ?? ''),
      name: p.name || null,
      domain: p.domain || p.website || null,
      employees: p.numberofemployees ? Number(p.numberofemployees) : null,
      ownerId: p.hubspot_owner_id || null,
      baselineJson: p.hiring_dept_headcount_json || '',
      lastScannedAt: p.hiring_last_scanned_at || null,
      lastAlertedAt: p.hiring_last_alerted_at || null,
      tier: p.hiring_velocity_tier || '',
    });
  }
}
return [{ json: { source: 'hubspot', pagesFetched, accounts } }];

// ─────────────────────────────────────────────────────────────────────────────
// Parse Sheet Scope
// Converts a Google Sheets values.get response into raw accounts. The first
// row is the header. Recognised columns (case-insensitive):
//   company_name, domain, employees, hubspot_company_id, owner_id,
//   baseline_json, last_scanned_at, last_alerted_at, tier
// Rows without a HubSpot company ID are scored and alerted but never synced.
// ─────────────────────────────────────────────────────────────────────────────
const rows = Array.isArray($input.first().json.values) ? $input.first().json.values : [];
if (rows.length < 2) return [{ json: { source: 'google-sheets', pagesFetched: 1, accounts: [] } }];

const header = rows[0].map((h) => String(h || '').trim().toLowerCase());
const col = (name) => header.indexOf(name);
const get = (row, name) => {
  const i = col(name);
  return i >= 0 && row[i] !== undefined ? String(row[i]).trim() : '';
};

const accounts = rows.slice(1)
  .filter((row) => row.some((c) => String(c || '').trim() !== ''))
  .map((row) => ({
    companyId: /^\d+$/.test(get(row, 'hubspot_company_id')) ? get(row, 'hubspot_company_id') : null,
    name: get(row, 'company_name') || null,
    domain: get(row, 'domain') || null,
    employees: get(row, 'employees') ? Number(get(row, 'employees')) : null,
    ownerId: get(row, 'owner_id') || null,
    baselineJson: get(row, 'baseline_json'),
    lastScannedAt: get(row, 'last_scanned_at') || null,
    lastAlertedAt: get(row, 'last_alerted_at') || null,
    tier: get(row, 'tier'),
  }));

return [{ json: { source: 'google-sheets', pagesFetched: 1, accounts } }];

// ─────────────────────────────────────────────────────────────────────────────
// Normalize Target Accounts
// Normalises domains, drops invalid/consumer/reserved domains, de-duplicates
// by domain, parses the stored rolling baseline, honours MIN_RESCAN_HOURS and
// caps the run at MAX_ACCOUNTS_PER_RUN. Emits one item per account to scan.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { source, pagesFetched, accounts = [] } = $input.first().json;
const HOUR_MS = 60 * 60 * 1000;

const CONSUMER = ['gmail.com', 'googlemail.com', 'yahoo.com', 'outlook.com', 'hotmail.com', 'live.com', 'icloud.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'mail.com', 'yandex.com', 'zoho.com', 'qq.com'];
const RESERVED_TLDS = ['test', 'invalid', 'localhost', 'local', 'internal', 'lan'];
// .example is accepted only for sandbox runs and manual test executions.
if (!cfg.sandboxMode && cfg.executionMode === 'production') RESERVED_TLDS.push('example');
const DOMAIN_RE = /^(?=.{4,253}$)(?:(?!-)[a-z0-9-]{1,63}(?<!-)\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{2,59})$/;

function normalizeDomain(raw) {
  let d = String(raw || '').trim().toLowerCase();
  if (!d) return null;
  if (d.includes('@')) d = d.split('@').pop();
  d = d.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').split(/[/?#]/)[0];
  d = d.replace(/:\d+$/, '').replace(/\.+$/, '').replace(/^www\d?\./, '');
  return d || null;
}
function parseBaseline(raw) {
  if (!raw) return null;
  try {
    const b = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (!b || typeof b !== 'object' || !b.capturedAt) return null;
    const departments = {};
    for (const [k, v] of Object.entries(b.departments || {})) if (Number.isFinite(Number(v))) departments[k] = Number(v);
    return {
      capturedAt: b.capturedAt,
      employees: Number.isFinite(Number(b.employees)) ? Number(b.employees) : null,
      departments,
      openRolesTarget: Number.isFinite(Number(b.openRolesTarget)) ? Number(b.openRolesTarget) : null,
    };
  } catch (e) {
    return null;
  }
}

const stats = { source, pagesFetched, received: accounts.length, invalidDomain: 0, consumerDomain: 0, reservedTld: 0, duplicate: 0, recentlyScanned: 0, overCap: 0, selected: 0 };
const seen = new Set();
const selected = [];

for (const a of accounts) {
  const domain = normalizeDomain(a.domain);
  if (!domain || !DOMAIN_RE.test(domain)) { stats.invalidDomain += 1; continue; }
  if (RESERVED_TLDS.includes(domain.split('.').pop())) { stats.reservedTld += 1; continue; }
  if (CONSUMER.some((c) => domain === c || domain.endsWith(`.${c}`))) { stats.consumerDomain += 1; continue; }
  if (seen.has(domain)) { stats.duplicate += 1; continue; }
  seen.add(domain);

  const lastScanMs = a.lastScannedAt ? Date.parse(a.lastScannedAt) : NaN;
  if (!cfg.sandboxMode && Number.isFinite(lastScanMs) && Date.now() - lastScanMs < cfg.minRescanHours * HOUR_MS) {
    stats.recentlyScanned += 1;
    continue;
  }
  if (selected.length >= cfg.maxAccountsPerRun) { stats.overCap += 1; continue; }

  selected.push({
    companyId: a.companyId ? String(a.companyId) : null,
    name: String(a.name || domain).trim().slice(0, 200),
    domain,
    employees: Number.isFinite(Number(a.employees)) && a.employees !== null ? Number(a.employees) : null,
    ownerId: a.ownerId ? String(a.ownerId) : null,
    baseline: parseBaseline(a.baselineJson),
    lastAlertedAt: a.lastAlertedAt || null,
    previousTier: a.tier || null,
  });
}
stats.selected = selected.length;

if (selected.length === 0) return [{ json: { domain: null, skipReason: 'No eligible target accounts in scope.', stats } }];
return selected.map((s) => ({ json: { ...s, scopeStats: stats } }));

// ─────────────────────────────────────────────────────────────────────────────
// Mock Hiring Intelligence (SANDBOX_MODE=true or no live provider enabled)
// Fictitious Apollo- and Clay-shaped signals per account, already normalised
// to the shape emitted by the live Attach nodes. Profiles are chosen so the
// sandbox shows one hot, one warm, one cool and one first-scan account.
// ─────────────────────────────────────────────────────────────────────────────
const DAY_MS = 24 * 60 * 60 * 1000;
const ago = (days) => new Date(Date.now() - days * DAY_MS).toISOString().slice(0, 10);
const jobs = (domain, list) => list.map(([title, days, location], i) => ({
  title, department: null, postedAt: ago(days), location, url: `https://careers.${domain}/jobs/${1000 + i}`,
}));

const PROFILES = {
  'apex-dynamics.example': {
    apollo: { employees: 905, growth6mPct: 14.2, deptHeadcount: { Engineering: 168, Sales: 71, Marketing: 27, 'Customer Success': 33 } },
    jobs: [
      ['Senior Software Engineer, Platform', 3, 'Remote, US'], ['Staff Backend Engineer', 5, 'Austin, TX'],
      ['Site Reliability Engineer', 6, 'Remote, US'], ['Engineering Manager, Payments', 9, 'Denver, CO'],
      ['Machine Learning Engineer', 11, 'Remote, US'], ['Frontend Engineer', 12, 'Austin, TX'],
      ['Security Engineer', 14, 'Remote, US'], ['DevOps Engineer', 18, 'Denver, CO'],
      ['Account Executive, Enterprise', 4, 'Chicago, IL'], ['Sales Development Representative', 7, 'Chicago, IL'],
      ['Sales Engineer', 10, 'Remote, US'], ['Product Marketing Manager', 15, 'Remote, US'],
    ],
    clayExtra: [['QA Automation Engineer', 2, 'Remote, US'], ['Senior Software Engineer, Platform', 3, 'Remote, US']],
  },
  'brightline-robotics.example': {
    apollo: { employees: 331, growth6mPct: 6.1, deptHeadcount: { Engineering: 74, Sales: 34, Marketing: 12 } },
    jobs: [
      ['Account Executive, Mid-Market', 2, 'Boston, MA'], ['Account Executive, Enterprise', 6, 'Remote, US'],
      ['Business Development Representative', 8, 'Boston, MA'], ['Regional Sales Manager', 13, 'Remote, US'],
      ['Sales Development Representative', 16, 'Boston, MA'], ['Solutions Consultant', 20, 'Remote, US'],
      ['Firmware Engineer', 22, 'Boston, MA'],
    ],
    clayExtra: [],
  },
  'cobalt-ridge-analytics.example': {
    apollo: { employees: 141, growth6mPct: 1.0, deptHeadcount: { Engineering: 41, Sales: 15 } },
    jobs: [['Data Engineer', 19, 'Remote, US'], ['Customer Success Manager', 25, 'Remote, US']],
    clayExtra: [],
  },
  'driftwood-health.example': {
    apollo: { employees: 2260, growth6mPct: 22.4, deptHeadcount: { Engineering: 310, Sales: 140, Operations: 420 } },
    jobs: [
      ['Software Engineer, Integrations', 4, 'Nashville, TN'], ['Implementation Specialist', 6, 'Remote, US'],
      ['Account Executive, Health Systems', 9, 'Remote, US'], ['Revenue Operations Analyst', 12, 'Nashville, TN'],
    ],
    clayExtra: [['Clinical Operations Manager', 3, 'Nashville, TN']],
  },
};

return $input.all().map((item) => {
  const a = item.json;
  const p = PROFILES[a.domain] || {
    apollo: { employees: a.employees, growth6mPct: 0, deptHeadcount: {} },
    jobs: [['Software Engineer', 10, 'Remote, US']],
    clayExtra: [],
  };
  const apolloJobs = jobs(a.domain, p.jobs);
  const clayJobs = jobs(a.domain, [...p.jobs.slice(0, 3), ...p.clayExtra]).map((j) => ({ ...j, url: `${j.url}?src=clay` }));
  return {
    json: {
      ...a,
      apollo: { provider: 'apollo', organizationId: `syn-org-${a.companyId || a.domain}`, ...p.apollo, jobs: apolloJobs, error: null },
      clay: { provider: 'clay', employees: p.apollo.employees, growth6mPct: null, deptHeadcount: {}, jobs: clayJobs, error: null },
      mock: true,
    },
  };
});

// ─────────────────────────────────────────────────────────────────────────────
// Attach Apollo Signals
// Combines Apollo organization enrichment (headcount, departmental headcount,
// growth) with the organization job postings response. HTTP nodes emit one
// item per input, so the account, enrichment and postings align by index.
// ─────────────────────────────────────────────────────────────────────────────
const accounts = $('Apollo Enabled?').all();
const enrich = $('Apollo: Enrich Organization').all();

// Apollo departmental_head_count keys → radar departments.
const DEPT_MAP = {
  engineering: 'Engineering', information_technology: 'Engineering',
  sales: 'Sales', business_development: 'Sales',
  marketing: 'Marketing',
  support: 'Customer Success',
  product_management: 'Product', arts_and_design: 'Product',
  data_science: 'Data',
  operations: 'Operations',
  finance: 'Finance', accounting: 'Finance',
  human_resources: 'People',
};
const pct = (v) => (v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Math.round(Number(v) * 1000) / 10);

return $input.all().map((item, i) => {
  const account = accounts[i] ? accounts[i].json : {};
  const e = enrich[i] ? enrich[i].json : {};
  const org = e.organization || {};
  const errors = [e.error, item.json.error].filter(Boolean).map((x) => String(x.message || x));

  const deptHeadcount = {};
  for (const [k, v] of Object.entries(org.departmental_head_count || {})) {
    const dept = DEPT_MAP[k];
    if (dept && Number.isFinite(Number(v))) deptHeadcount[dept] = (deptHeadcount[dept] || 0) + Number(v);
  }

  const postings = Array.isArray(item.json.organization_job_postings) ? item.json.organization_job_postings : [];
  const jobs = postings.map((p) => ({
    title: String(p.title || '').slice(0, 160),
    department: null,
    postedAt: p.posted_at ? String(p.posted_at).slice(0, 10) : (p.last_seen_at ? String(p.last_seen_at).slice(0, 10) : null),
    location: [p.city, p.state, p.country].filter(Boolean).join(', ') || null,
    url: p.url ? String(p.url) : null,
  })).filter((j) => j.title);

  return {
    json: {
      ...account,
      apollo: {
        provider: 'apollo',
        organizationId: org.id || null,
        employees: Number.isFinite(Number(org.estimated_num_employees)) ? Number(org.estimated_num_employees) : null,
        growth6mPct: pct(org.organization_headcount_six_month_growth),
        growth12mPct: pct(org.organization_headcount_twelve_month_growth),
        deptHeadcount,
        jobs,
        error: errors.length ? errors.join(' | ') : null,
      },
    },
  };
});

// ─────────────────────────────────────────────────────────────────────────────
// Attach Clay Signals
// Normalises the response of your Clay hiring endpoint. The adapter accepts
// the documented contract (README §7.11) and common variants:
//   jobs | open_roles | data.jobs            → [{ title, department?, posted_at?, location?, url? }]
//   headcount.total | employee_count         → number
//   headcount.by_department | departments    → { "<Department>": number }
//   headcount_growth_90d_pct | growth_pct    → number (percent)
// Items align by index with the Clay Enabled? gate output.
// ─────────────────────────────────────────────────────────────────────────────
const bases = $('Clay Enabled?').all();
const CANON = ['Engineering', 'Sales', 'Marketing', 'Customer Success', 'Product', 'Data', 'Operations', 'Finance', 'People'];
const canon = (k) => CANON.find((c) => c.toLowerCase() === String(k).trim().toLowerCase().replace(/_/g, ' ')) || null;

return $input.all().map((item, i) => {
  const base = bases[i] ? bases[i].json : {};
  const b = item.json || {};
  const rawJobs = b.jobs || b.open_roles || (b.data && b.data.jobs) || [];
  const jobs = (Array.isArray(rawJobs) ? rawJobs : []).map((j) => ({
    title: String(j.title || j.job_title || '').slice(0, 160),
    department: j.department ? canon(j.department) : null,
    postedAt: j.posted_at || j.postedAt || j.date ? String(j.posted_at || j.postedAt || j.date).slice(0, 10) : null,
    location: j.location || null,
    url: j.url || j.job_url || null,
  })).filter((j) => j.title);

  const hc = b.headcount || {};
  const deptRaw = hc.by_department || b.departments || {};
  const deptHeadcount = {};
  for (const [k, v] of Object.entries(deptRaw)) {
    const d = canon(k);
    if (d && Number.isFinite(Number(v))) deptHeadcount[d] = Number(v);
  }
  const employees = Number(hc.total ?? b.employee_count);
  const growth = Number(b.headcount_growth_90d_pct ?? b.growth_pct);

  return {
    json: {
      ...base,
      clay: {
        provider: 'clay',
        employees: Number.isFinite(employees) ? employees : null,
        growth6mPct: null,
        growth90dPct: Number.isFinite(growth) ? growth : null,
        deptHeadcount,
        jobs,
        error: b.error ? String(b.error.message || b.error) : null,
      },
    },
  };
});

// ─────────────────────────────────────────────────────────────────────────────
// Score Hiring Velocity
// Merges provider signals per account, classifies roles by department,
// computes velocity deltas against the rolling baseline, and evaluates the
// spike thresholds. Produces the score, tier, triggers, alert decision and
// the next baseline snapshot.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();

// Order matters: "Sales Engineer" is Sales, "Support Engineer" is Customer Success.
const RULES = [
  ['Sales', /\b(sales|account executive|\bae\b|sdr|bdr|business development|account manager|solutions consultant|revenue)\b/i],
  ['Customer Success', /\b(customer success|support|implementation|onboarding|customer experience|technical account)\b/i],
  ['Data', /\b(data (scien|engineer|analy)|analytics|machine learning|\bml\b|\bai\b)/i],
  ['Engineering', /\b(engineer|engineering|developer|devops|sre|software|platform|architect|\bqa\b|firmware|security)\b/i],
  ['Product', /\b(product manager|product owner|\bux\b|\bui\b|designer|design lead)\b/i],
  ['Marketing', /\b(marketing|demand gen|content|brand|seo|growth|communications)\b/i],
  ['Operations', /\b(operations|logistics|supply chain|procurement|clinical)\b/i],
  ['Finance', /\b(finance|accountant|controller|fp&a|payroll|treasury)\b/i],
  ['People', /\b(recruit|talent|people|human resources|\bhr\b)\b/i],
];
const classify = (title) => (RULES.find(([, re]) => re.test(title)) || ['Other'])[0];
const targets = cfg.targetDepartments;
const tierRank = { cool: 0, warm: 1, hot: 2 };
const round1 = (n) => Math.round(n * 10) / 10;

return $input.all().map((item) => {
  const a = item.json;
  const providers = [a.apollo, a.clay].filter(Boolean);
  const errors = providers.map((p) => p.error && `${p.provider}: ${p.error}`).filter(Boolean);

  // ── Jobs: union, de-duplicate, recency window, classify ─────────────────
  const jobMap = new Map();
  for (const p of providers) {
    for (const j of p.jobs || []) {
      const key = `${j.title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()}|${String(j.location || '').toLowerCase()}`;
      if (jobMap.has(key)) { jobMap.get(key).sources.push(p.provider); continue; }
      const postedMs = j.postedAt ? Date.parse(j.postedAt) : NaN;
      if (Number.isFinite(postedMs) && now - postedMs > cfg.jobLookbackDays * DAY_MS) continue;
      jobMap.set(key, { ...j, department: j.department || classify(j.title), ageDays: Number.isFinite(postedMs) ? Math.floor((now - postedMs) / DAY_MS) : null, sources: [p.provider] });
    }
  }
  const jobs = [...jobMap.values()];
  const rolesByDept = {};
  for (const j of jobs) rolesByDept[j.department] = (rolesByDept[j.department] || 0) + 1;
  const targetRoles = jobs.filter((j) => targets.includes(j.department));
  const openRolesTarget = targetRoles.length;
  const freshTargetRoles = targetRoles.filter((j) => j.ageDays !== null && j.ageDays <= 7).length;

  // ── Headcount: Apollo first, Clay as fallback ───────────────────────────
  const deptNow = Object.keys(a.apollo?.deptHeadcount || {}).length ? a.apollo.deptHeadcount : (a.clay?.deptHeadcount || {});
  const employeesNow = a.apollo?.employees ?? a.clay?.employees ?? a.employees ?? null;
  const base = a.baseline;

  const deptGrowth = {};
  let topDept = null;
  for (const d of targets) {
    const cur = deptNow[d];
    const prev = base?.departments?.[d];
    if (Number.isFinite(cur) && Number.isFinite(prev) && prev >= cfg.minDeptBaseline) {
      deptGrowth[d] = round1(((cur - prev) / prev) * 100);
      if (!topDept || deptGrowth[d] > deptGrowth[topDept]) topDept = d;
    }
  }

  let totalGrowthPct = null;
  let totalGrowthBasis = null;
  if (base?.employees && employeesNow) {
    totalGrowthPct = round1(((employeesNow - base.employees) / base.employees) * 100);
    totalGrowthBasis = 'baseline';
  } else if (a.apollo?.growth6mPct !== null && a.apollo?.growth6mPct !== undefined) {
    totalGrowthPct = a.apollo.growth6mPct;
    totalGrowthBasis = 'apollo_6m';
  } else if (a.clay?.growth90dPct !== null && a.clay?.growth90dPct !== undefined) {
    totalGrowthPct = a.clay.growth90dPct;
    totalGrowthBasis = 'clay_90d';
  }

  // ── Triggers and score ──────────────────────────────────────────────────
  const topGrowth = topDept ? deptGrowth[topDept] : null;
  const triggers = [];
  if (topGrowth !== null && topGrowth >= cfg.deptGrowthThresholdPct) triggers.push(`dept_surge:${topDept}`);
  if (openRolesTarget > cfg.openRolesThreshold) triggers.push('open_roles_spike');
  if (totalGrowthPct !== null && totalGrowthPct >= cfg.totalGrowthThresholdPct) triggers.push('headcount_surge');

  const components = {
    deptGrowth: topGrowth > 0 ? Math.min(40, (topGrowth / cfg.deptGrowthThresholdPct) * 28) : 0,
    openRoles: Math.min(35, (openRolesTarget / Math.max(1, cfg.openRolesThreshold)) * 21),
    totalGrowth: totalGrowthPct > 0 ? Math.min(15, (totalGrowthPct / cfg.totalGrowthThresholdPct) * 10) : 0,
    freshness: Math.min(10, freshTargetRoles * 2),
  };
  const score = Math.round(Object.values(components).reduce((s, v) => s + v, 0));
  const tier = score >= 70 || triggers.length >= 2 ? 'hot' : score >= 45 || triggers.length === 1 ? 'warm' : 'cool';

  const lastAlertMs = a.lastAlertedAt ? Date.parse(a.lastAlertedAt) : NaN;
  const inCooldown = Number.isFinite(lastAlertMs) && now - lastAlertMs < cfg.alertCooldownDays * DAY_MS;
  const meetsTier = tierRank[tier] >= tierRank[cfg.alertMinTier];
  const alert = meetsTier && triggers.length > 0 && !inCooldown;

  // ── Rolling baseline: roll forward only when older than the window ──────
  const baseAgeDays = base?.capturedAt ? (now - Date.parse(base.capturedAt)) / DAY_MS : Infinity;
  const nextBaseline = !base || baseAgeDays >= cfg.baselineWindowDays
    ? { capturedAt: new Date(now).toISOString(), employees: employeesNow, departments: deptNow, openRolesTarget }
    : base;

  const parts = [];
  if (topGrowth !== null) parts.push(`${topDept} headcount ${topGrowth >= 0 ? '+' : ''}${topGrowth}% vs. baseline`);
  parts.push(`${openRolesTarget} open ${targets.join('/')} roles (${freshTargetRoles} in last 7 days)`);
  if (totalGrowthPct !== null) parts.push(`total headcount ${totalGrowthPct >= 0 ? '+' : ''}${totalGrowthPct}% (${totalGrowthBasis})`);

  return {
    json: {
      companyId: a.companyId,
      name: a.name,
      domain: a.domain,
      ownerId: a.ownerId,
      previousTier: a.previousTier,
      score,
      tier,
      triggers,
      alert,
      alertSuppressedReason: !alert ? (triggers.length === 0 ? 'no_trigger' : !meetsTier ? 'below_alert_tier' : inCooldown ? 'cooldown' : null) : null,
      components: Object.fromEntries(Object.entries(components).map(([k, v]) => [k, round1(v)])),
      metrics: {
        employeesNow, totalGrowthPct, totalGrowthBasis, deptNow, deptGrowth, topDept, topGrowth,
        openRolesTotal: jobs.length, openRolesTarget, freshTargetRoles, rolesByDept,
        baselineCapturedAt: base?.capturedAt || null, baselineAgeDays: Number.isFinite(baseAgeDays) ? Math.round(baseAgeDays) : null,
      },
      summary: parts.join(' · '),
      sampleRoles: targetRoles.sort((x, y) => (x.ageDays ?? 99) - (y.ageDays ?? 99)).slice(0, 5).map((j) => ({ title: j.title, department: j.department, location: j.location, ageDays: j.ageDays, url: j.url })),
      nextBaseline,
      providers: providers.map((p) => p.provider),
      providerErrors: errors,
      mock: Boolean(a.mock),
    },
  };
});

// ─────────────────────────────────────────────────────────────────────────────
// Compose Sync & Alert Payloads
// Builds three batch payloads for the whole run:
//   1. HubSpot companies batch update (radar properties on every scanned account)
//   2. HubSpot tasks batch create (high-intent SDR tasks for alerted accounts)
//   3. One Slack Block Kit digest of alerted accounts
// Accounts without a HubSpot company ID (sheet-only rows) are alerted but
// never synced.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const scope = $('Normalize Target Accounts').first().json.scopeStats || {};
const accounts = $input.all().map((i) => i.json);
const nowIso = new Date().toISOString();
const HOUR_MS = 60 * 60 * 1000;
const TIER_EMOJI = { hot: '🔥', warm: '🌡️', cool: '❄️' };
// Account names and job titles come from external systems: escape before rendering HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const alerted = accounts.filter((a) => a.alert).sort((x, y) => y.score - x.score);
const recordUrl = (id) => (cfg.portalId && id ? `${cfg.hubspotUiBaseUrl}/contacts/${cfg.portalId}/record/0-2/${id}` : null);

// ── 1. Company property updates ───────────────────────────────────────────
const updates = accounts.filter((a) => a.companyId).map((a) => {
  const properties = {
    hiring_velocity_score: String(a.score),
    hiring_velocity_tier: a.tier,
    hiring_open_roles_target: String(a.metrics.openRolesTarget),
    hiring_open_roles_total: String(a.metrics.openRolesTotal),
    hiring_signal_summary: `${a.summary}${a.triggers.length ? ` · triggers: ${a.triggers.join(', ')}` : ''}`.slice(0, 1000),
    hiring_dept_headcount_json: JSON.stringify(a.nextBaseline),
    hiring_last_scanned_at: nowIso,
  };
  if (a.alert) properties.hiring_last_alerted_at = nowIso;
  return { id: String(a.companyId), properties };
});

// ── 2. SDR tasks ──────────────────────────────────────────────────────────
const taskBody = (a) => [
  `<p><strong>Hiring velocity alert: ${esc(a.name)}</strong> (${esc(a.domain)})</p>`,
  `<p>Score <strong>${a.score}/100</strong> · tier <strong>${a.tier.toUpperCase()}</strong> · triggers: ${esc(a.triggers.join(', '))}</p>`,
  `<p>${esc(a.summary)}</p>`,
  a.sampleRoles.length ? `<p>Recent target-department roles:</p><ul>${a.sampleRoles.map((r) => `<li>${esc(r.title)} (${esc(r.department)}${r.location ? `, ${esc(r.location)}` : ''}${r.ageDays !== null ? `, ${r.ageDays}d ago` : ''})</li>`).join('')}</ul>` : '',
  '<p><em>Suggested play: reference the team expansion, not the job post itself. Lead with the operational pain that follows rapid hiring in the surging department.</em></p>',
  `<p><em>Generated by n8n-clay-hiring-velocity-target-account-radar (dhRobin Systems), run ${cfg.runId}. Verify signals before outreach.</em></p>`,
].join('');

const tasks = cfg.createSdrTasks ? alerted.filter((a) => a.companyId).map((a) => {
  const ownerId = a.ownerId || cfg.sdrDefaultOwnerId || null;
  const properties = {
    hs_timestamp: new Date(Date.now() + cfg.taskDueHours * HOUR_MS).toISOString(),
    hs_task_subject: `${TIER_EMOJI[a.tier]} Hiring surge: ${a.name} (score ${a.score})`.slice(0, 250),
    hs_task_body: taskBody(a),
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: a.tier === 'hot' ? 'HIGH' : 'MEDIUM',
    hs_task_type: 'TODO',
  };
  if (ownerId) properties.hubspot_owner_id = String(ownerId);
  return {
    properties,
    associations: [{ to: { id: String(a.companyId) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 192 }] }],
  };
}) : [];

// ── 3. Slack digest ───────────────────────────────────────────────────────
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
const modeTags = [cfg.sandboxMode ? 'SANDBOX' : 'LIVE', cfg.dryRun ? 'DRY RUN' : 'SYNCED', `providers: ${cfg.hiringLive ? cfg.hiringProviders.join('+') : 'mock'}`].join(' · ');
const accountBlocks = alerted.slice(0, 10).flatMap((a) => {
  const link = recordUrl(a.companyId);
  const roles = a.sampleRoles.slice(0, 3).map((r) => `• ${r.title}${r.ageDays !== null ? ` _(${r.ageDays}d)_` : ''}`).join('\n');
  const block = {
    type: 'section',
    text: { type: 'mrkdwn', text: clip(`${TIER_EMOJI[a.tier]} *${a.name}* (${a.domain}): score *${a.score}*, ${a.tier}\n${a.summary}\n${roles}`, 2900) },
  };
  if (link) block.accessory = { type: 'button', text: { type: 'plain_text', text: 'Open in HubSpot' }, url: link };
  return [block, { type: 'divider' }];
});
const tierCounts = accounts.reduce((m, a) => ({ ...m, [a.tier]: (m[a.tier] || 0) + 1 }), {});
const slackPayload = {
  text: `Hiring velocity radar: ${alerted.length} account(s) heating up`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `📡 Hiring Velocity Radar: ${alerted.length} account${alerted.length === 1 ? '' : 's'} heating up` } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: clip(`Scanned *${accounts.length}* · 🔥 ${tierCounts.hot || 0} · 🌡️ ${tierCounts.warm || 0} · ❄️ ${tierCounts.cool || 0} · ${modeTags}`, 2900) }] },
    { type: 'divider' },
    ...accountBlocks,
    ...(alerted.length > 10 ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `+${alerted.length - 10} more in HubSpot (filter: hiring_velocity_tier).` }] }] : []),
    { type: 'context', elements: [{ type: 'mrkdwn', text: `n8n-clay-hiring-velocity-target-account-radar · dhRobin Systems · run ${cfg.runId}` }] },
  ],
};

return [{
  json: {
    dryRun: cfg.dryRun,
    syncToHubspot: cfg.syncToHubspot,
    notifySlack: cfg.notifySlack,
    counts: { scanned: accounts.length, alerted: alerted.length, updates: updates.length, tasks: tasks.length, ...tierCounts },
    scope,
    hubspotBatchUpdate: { inputs: updates },
    hubspotTaskBatch: { inputs: tasks },
    slackPayload,
    accounts: accounts.map((a) => ({ name: a.name, domain: a.domain, companyId: a.companyId, score: a.score, tier: a.tier, triggers: a.triggers, alert: a.alert, alertSuppressedReason: a.alertSuppressedReason, summary: a.summary, providerErrors: a.providerErrors })),
  },
}];
